using System.ComponentModel;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using System.Text.Json;
using System.Windows;
using System.Windows.Interop;

namespace LostWindows;

/// <summary>Restores saved placement; callers must use EnsureVisible after every Show to recover inaccessible windows.</summary>
public static class WindowLayout
{
    private static readonly Dictionary<string, Placement> Placements = Load();

    public static void Restore(Window window, string key)
    {
        if (!Placements.TryGetValue(key, out Placement? placement))
        {
            return;
        }

        if (placement is null || !double.IsFinite(placement.Left) || !double.IsFinite(placement.Top)
            || !double.IsFinite(placement.Width) || !double.IsFinite(placement.Height)
            || placement.Width <= 0 || placement.Height <= 0
            || !Enum.TryParse(placement.State, out WindowState state) || !Enum.IsDefined(state))
        {
            Trace.TraceWarning("Ignoring invalid window placement for '{0}'.", key);
            window.WindowStartupLocation = WindowStartupLocation.CenterOwner;
            return;
        }

        window.WindowStartupLocation = WindowStartupLocation.Manual;
        window.Left = placement.Left;
        window.Top = placement.Top;
        window.Width = Math.Clamp(placement.Width, window.MinWidth, window.MaxWidth);
        window.Height = Math.Clamp(placement.Height, window.MinHeight, window.MaxHeight);
        window.WindowState = state == WindowState.Minimized ? WindowState.Normal : state;
    }

    public static void EnsureVisible(Window window)
    {
        if (window.WindowState == WindowState.Minimized)
        {
            window.WindowState = WindowState.Normal;
        }

        if (window.WindowState == WindowState.Maximized)
        {
            return;
        }

        window.UpdateLayout();
        IntPtr handle = new WindowInteropHelper(window).Handle;
        if (!GetWindowRect(handle, out NativeRect bounds))
        {
            throw new Win32Exception(Marshal.GetLastWin32Error());
        }

        var monitor = new MonitorInfo { Size = Marshal.SizeOf<MonitorInfo>() };
        if (!GetMonitorInfo(MonitorFromWindow(handle, 2), ref monitor))
        {
            throw new Win32Exception(Marshal.GetLastWin32Error());
        }

        // Use physical pixels from the actual HWND, not WPF DIPs, for mixed-DPI monitors and taskbars.
        NativeRect work = monitor.Work;
        int width = Math.Min(bounds.Right - bounds.Left, work.Right - work.Left);
        int height = Math.Min(bounds.Bottom - bounds.Top, work.Bottom - work.Top);
        int left = Math.Clamp(bounds.Left, work.Left, work.Right - width);
        int top = Math.Clamp(bounds.Top, work.Top, work.Bottom - height);
        if (left != bounds.Left || top != bounds.Top
            || width != bounds.Right - bounds.Left || height != bounds.Bottom - bounds.Top)
        {
            Trace.TraceWarning("Recovering inaccessible placement for '{0}'.", window.Title);
            if (!SetWindowPos(handle, IntPtr.Zero, left, top, width, height, 0x0014))
            {
                throw new Win32Exception(Marshal.GetLastWin32Error());
            }
        }
    }

    private static Dictionary<string, Placement> Load()
    {
        string path = Path.Combine(AppContext.BaseDirectory, "layout.json");
        if (!File.Exists(path))
        {
            return new();
        }

        try
        {
            var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
            return JsonSerializer.Deserialize<Dictionary<string, Placement>>(File.ReadAllText(path), options)
                ?? throw new JsonException("Window layout must contain an object.");
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or JsonException)
        {
            Trace.TraceWarning("Cannot restore window layout '{0}': {1}", path, ex.Message);
            return new();
        }
    }

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool GetWindowRect(IntPtr window, out NativeRect rect);

    [DllImport("user32.dll")]
    private static extern IntPtr MonitorFromWindow(IntPtr window, uint flags);

    [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool GetMonitorInfo(IntPtr monitor, ref MonitorInfo info);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool SetWindowPos(IntPtr window, IntPtr insertAfter, int x, int y, int width, int height, uint flags);

    [StructLayout(LayoutKind.Sequential)]
    private struct NativeRect
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct MonitorInfo
    {
        public int Size;
        public NativeRect Monitor;
        public NativeRect Work;
        public uint Flags;
    }

    private sealed record Placement(double Left, double Top, double Width, double Height, string State);

