using System.IO;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Interop;
using System.Windows.Media;
using LostWindows;

internal static class Program
{
    [STAThread]
    private static void Main(string[] args)
    {
        string scenario = args.Length == 0 ? "original" : args[0];
        string layout = scenario switch
        {
            "original" => File.ReadAllText(@"Q:\source\XamlAgentDemos\src\LostWindows\layout.json"),
            "malformed" => "{ broken json",
            "null" => "null",
            "null-placement" => "{\"settings\":null}",
            "invalid-state" => "{\"settings\":{\"left\":40,\"top\":40,\"width\":420,\"height\":360,\"state\":\"999\"}}",
            "invalid-size" => "{\"settings\":{\"left\":40,\"top\":40,\"width\":-1,\"height\":0,\"state\":\"Normal\"}}",
            "oversized" => "{\"settings\":{\"left\":-32000,\"top\":-32000,\"width\":10000,\"height\":10000,\"state\":\"Normal\"}}",
            _ => throw new ArgumentException(scenario)
        };
        File.WriteAllText(Path.Combine(AppContext.BaseDirectory, "layout.json"), layout);
        var app = new Application { ShutdownMode = ShutdownMode.OnExplicitShutdown };
        var main = new MainWindow();
        main.Show();
        foreach (string title in new[] { "Settings", "Notifications", "Inspector" })
        {
            Button button = (Button)main.FindName(title + "Button");
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            Window window = app.Windows.Cast<Window>().Single(w => w.Title == title);
            VerifyVisible(window);
            if (window is InspectorWindow inspector)
            {
                Assert(inspector.ActualWidth >= 280 && inspector.ActualHeight >= 160, "Inspector minimum size");
                Assert(Descendants(inspector).OfType<TextBlock>().Any(t => t.IsVisible && t.Text.Contains("Select a note")), "Inspector empty state");
                inspector.DataContext = new { HasSelection = true, SelectedTitle = "Regression note", WordCount = 17 };
                inspector.UpdateLayout();
                Assert(Descendants(inspector).OfType<TextBlock>().Any(t => t.IsVisible && t.Text == "Regression note"), "Inspector selection state");
                Assert(!Descendants(inspector).OfType<TextBlock>().Any(t => t.IsVisible && t.Text.Contains("Select a note")), "Empty state hides on selection");
            }
            window.WindowState = WindowState.Minimized;
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            VerifyVisible(window);
            window.Left = -32000;
            window.Top = -32000;
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            VerifyVisible(window);
            Assert(app.Windows.Cast<Window>().Count(w => w.Title == title) == 1, "Repeated open reuses window");
            window.Close();
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
            Window reopened = app.Windows.Cast<Window>().Single(w => w.Title == title);
            Assert(!ReferenceEquals(window, reopened), "Closed window recreated");
            VerifyVisible(reopened);
            reopened.Close();
        }
        main.Close();
        app.Shutdown();
        Console.WriteLine($"PASS {scenario}: all three windows visible; minimized/off-screen recovery; reuse; close/reopen; Inspector empty/selected states.");
    }

    private static IEnumerable<DependencyObject> Descendants(DependencyObject parent)
    {
        for (int i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++)
        {
            DependencyObject child = VisualTreeHelper.GetChild(parent, i);
            yield return child;
            foreach (DependencyObject descendant in Descendants(child)) yield return descendant;
        }
    }

    private static void VerifyVisible(Window window)
    {
        window.UpdateLayout();
        Assert(window.IsVisible && window.WindowState != WindowState.Minimized, "Window visible and not minimized");
        IntPtr handle = new WindowInteropHelper(window).Handle;
        Assert(GetWindowRect(handle, out Rect bounds), "Read native bounds");
        var monitor = new MonitorInfo { Size = Marshal.SizeOf<MonitorInfo>() };
        Assert(GetMonitorInfo(MonitorFromWindow(handle, 2), ref monitor), "Read monitor work area");
        Assert(bounds.Left >= monitor.Work.Left && bounds.Top >= monitor.Work.Top
            && bounds.Right <= monitor.Work.Right && bounds.Bottom <= monitor.Work.Bottom, "Full window inside monitor work area");
        Assert(bounds.Right - bounds.Left >= 100 && bounds.Bottom - bounds.Top >= 100, "Usable window dimensions");
    }

    private static void Assert(bool condition, string message)
    {
        if (!condition) throw new InvalidOperationException(message);
    }

    [DllImport("user32.dll")] private static extern bool GetWindowRect(IntPtr window, out Rect rect);
    [DllImport("user32.dll")] private static extern IntPtr MonitorFromWindow(IntPtr window, uint flags);
    [DllImport("user32.dll", CharSet = CharSet.Auto)] private static extern bool GetMonitorInfo(IntPtr monitor, ref MonitorInfo info);
    [StructLayout(LayoutKind.Sequential)] private struct Rect { public int Left, Top, Right, Bottom; }
    [StructLayout(LayoutKind.Sequential)] private struct MonitorInfo { public int Size; public Rect Monitor, Work; public uint Flags; }
}

